-- Public enterprises (owner, 23 November 2026: variant A, „companii de stat” are every public enterprise on the Ministry
-- of Finance list, central and local, as one kind of buyer; search probe of the same day).
-- Source: „Lista întreprinderilor publice (ÎP) monitorizate la nivelul Ministerului Finanțelor conform O.M.F.P. nr.
-- 2873/2016”, updated 21.10.2026 (https://static.anaf.ro/static/10/Anaf/Declaratii_R/S1001/liste.html, „05. Lista
-- publicare 21.10.2026.pdf”): 334 central and 1,361 local enterprises, each with its CUI (column 10 of the list), the
-- public authority that holds it (columns 4–5; never an enterprise itself) and its state. Read from the PDF by position;
-- every CUI passes the checksum, the two numberings (1–334, 1–1,361) are complete and no CUI repeats.
-- The site reads the CUIs as a list of buyers (apps/web/lib/ask/authority-kind.ts); enterprises in insolvency or
-- liquidation stay, their purchases are historical. A newer list is a new migration that replaces the rows.
-- Insert only, idempotent. seap_web reads the table through the reference schema's default privileges; the nightly
-- shadow build copies every reference table.
CREATE SCHEMA IF NOT EXISTS reference;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS reference.public_enterprise (
  cui text PRIMARY KEY,
  name text NOT NULL,
  level text NOT NULL CHECK (level IN ('central', 'local')),
  state text NOT NULL CHECK (state IN ('active', 'inactive')),
  state_text text,
  apt_cui text,
  apt_name text,
  county text,
  listed_on date NOT NULL,
  source text NOT NULL
);
--> statement-breakpoint
ON CONFLICT (cui) DO NOTHING;
